 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    up = down = 0
    # Each motif is a horizontal bar of three 2s with a single centered stem.
    for r in range(h):
        for c in range(w - 2):
            if grid[r][c:c+3] != [2, 2, 2]:
                continue
            mid = c + 1
            if r > 0 and grid[r-1][mid] == 2:
                up += 1  # stem above the bar
            if r + 1 < h and grid[r+1][mid] == 2:
                down += 1  # stem below the bar
    out = [[0] * 6 for _ in range(3)]
    spots = [(0, 0), (2, 0), (0, 2), (2, 2)]
    for i in range(min(up, 4)):
        r, c = spots[i]
        out[r][c] = 3
    for i in range(min(down, 4)):
        r, c = spots[i]
        out[r][c + 3] = 1
    return out
